//! The committed table is the one the schema produces.
//!
//! `src/gatt.rs` is generated by hand (`tool/gen_gatt.sh`) and checked in, so
//! nothing else in the build would notice a schema change that was never
//! regenerated — the firmware would keep serving the old table and the app would
//! have no way to tell. This regenerates in memory and compares.

use gatt_gen::generator::server::rust_trouble::{self, Config};

/// The committed file names the script in its own header, so the test has to
/// name it the same way the script names itself.
const REGENERATE_WITH: &str = "calypso-core/tool/gen_gatt.sh";

#[test]
fn the_committed_table_is_what_the_tool_generates() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("the crate is in the repo root");

    let input = gatt_gen::Input::new([root.join("proto/calypso_gatt.proto")]);
    let (schema, warnings) = gatt_gen::load(&input).expect("the schema loads and is valid");
    assert_eq!(
        warnings.len(),
        2,
        "the schema is expected to warn about both max_len values: {warnings:?}"
    );

    let generated = rust_trouble::generate(
        &schema,
        &Config {
            message_module: "crate::pb::msg".to_string(),
            server_name: "CalypsoGatt".to_string(),
            pipe_chunk_max: 244,
            pipe_msg_max: 0,
            regenerate_with: Some(REGENERATE_WITH.to_string()),
        },
    )
    .expect("the schema is emittable");

    assert_eq!(generated.file_name, "gatt.rs");
    assert_eq!(
        generated.source,
        include_str!("../src/gatt.rs"),
        "src/gatt.rs is stale: run {REGENERATE_WITH}"
    );
}
